-- ============================================================
-- 0015_eway_bills.sql
-- E-way bills recorded against an invoice. They are generated by staff on the government portal and uploaded here
-- (number, dates, vehicle and the PDF they downloaded); the app never calls the government.
-- REQUIREMENT: run as a role that bypasses RLS (superuser / DATABASE_ADMIN_URL), like 0003-0014.
-- ============================================================

CREATE TABLE IF NOT EXISTS "eway_bills" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE cascade,
  "invoice_id" uuid NOT NULL REFERENCES "invoices"("id"),
  "ewb_number" varchar(12) NOT NULL,
  "generated_on" date,
  "valid_until" date,
  "vehicle_number" varchar(12),
  "file_name" varchar(120),
  "mime_type" varchar(100),
  "size_bytes" integer,
  "data" bytea,
  "uploaded_by_id" uuid REFERENCES "users"("id"),
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "eway_bills_number_format" CHECK ("ewb_number" ~ '^[0-9]{12}$')
);
--> statement-breakpoint
-- The same e-way bill number cannot be recorded twice in a business.
CREATE UNIQUE INDEX IF NOT EXISTS "eway_bills_tenant_number_idx" ON "eway_bills" ("tenant_id", "ewb_number");
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "eway_bills_invoice_idx" ON "eway_bills" ("tenant_id", "invoice_id");
--> statement-breakpoint

ALTER TABLE "eway_bills" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE "eway_bills" FORCE ROW LEVEL SECURITY;
--> statement-breakpoint

DO $$ BEGIN
  DROP POLICY IF EXISTS tenant_isolation_eway_bills ON eway_bills;
  CREATE POLICY tenant_isolation_eway_bills ON eway_bills
    FOR ALL
    USING (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);
END $$;
--> statement-breakpoint

DO $$ BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'friendly_app_runtime') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON "eway_bills" TO friendly_app_runtime;
  END IF;
END $$;
